package main

import (
	"fmt"
	"strings"
	"bufio"
	"io"
)

func parseWithCurrentMethod(src io.Reader) {
	scanner := bufio.NewScanner(src)
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) > 0 && strings.TrimLeft(line, " ")[0] == '#' {
			continue
		}
		pivot := strings.IndexAny(line, " ")
		if pivot > 0 && pivot < len(line)-1 { // separator found
			key := line[0:pivot]
			value := strings.Trim(line[pivot+1:], " ")
			fmt.Printf("Key: '%s', Value: '%s'\n", key, value)
		}
	}
}

func parseWithImprovedMethod(src io.Reader) {
	scanner := bufio.NewScanner(src)
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) > 0 && strings.TrimLeft(line, " ")[0] == '#' {
			continue
		}
		// Use Fields to handle multiple spaces/tabs
		fields := strings.Fields(line)
		if len(fields) >= 2 {
			key := fields[0]
			value := strings.Join(fields[1:], " ")
			fmt.Printf("Key: '%s', Value: '%s'\n", key, value)
		}
	}
}

func main() {
	testData := "bind    0.0.0.0\nport\t\t6399\nappendonly   yes\n"

	fmt.Println("Current method:")
	parseWithCurrentMethod(strings.NewReader(testData))

	fmt.Println("\nImproved method:")
	parseWithImprovedMethod(strings.NewReader(testData))
